rss.channel:
  {{ site.name }}
  {{ origin }}{{ base }}
  {{ site.tagline }}
  {{ site.language }}
  {{ now }}

  {% for p in posts %}


    {{ p.headline }}
    {{ origin }}{{ base }}{{ p.url_path }}
    {{ origin }}{{ base }}{{ p.url_path }}
    {{ rfc(p.generated_at or p.date) }}
    {{ p.byline }}
    {% for t in p.tags %}{{ t }}{% endfor %}
    {{ p.dek_plain }}

<p><strong>The 30-second version</strong></p><ul>{% for b in p.what_post %}<li>{{ b.html }}</li>{% endfor %}</ul>
{% for s in p.sections_r %}<h2>{{ s.title }}</h2>{% for para in s.html %}<p>{{ para }}</p>{% endfor %}{% endfor %}
<h2>Why it matters</h2>{% for w in p.why_html %}<p>{% if w.speculative %}<em>Our read (analysis): </em>{% endif %}{{ w.html }}</p>{% endfor %}
<h2>Sources</h2><ol>{% for s in p.sources_r %}<li><a href="{{ s.url }}">{{ s.title }}</a> ({{ s.publisher }})</li>{% endfor %}</ol>
<p><a href="{{ origin }}{{ base }}{{ p.url_path }}">Read on the site, with charts and the verification log.</a></p>


  {% endfor %}
